def dfs_with_limit(graph, start, goal, limit):
    visited = set()

    def dfs(current, limit):
        if current == goal:
            return True
        if limit == 0:
            return False
        visited.add(current)
        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                if dfs(neighbor, limit - 1):
                    return True
        return False

    for depth in range(limit + 1):
        if dfs(start, depth):
            return True
    return False

def iterative_deepening_dfs(graph, start, goal):
